package com.erp.production.service.impl; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl; import com.erp.production.entity.ProductBom; import com.erp.production.mapper.ProductBomMapper; import com.erp.production.service.ProductBomService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class ProductBomServiceImpl extends ServiceImpl<ProductBomMapper, ProductBom> implements ProductBomService { @Override public List<ProductBom> getBomByProductId(Long productId) { LambdaQueryWrapper<ProductBom> w = new LambdaQueryWrapper<>(); w.eq(ProductBom::getProductId, productId); return list(w); } }